insert into thankyou.exchange_products(id,name,category,description,price,stock,active,icon) values('keyboard-mouse','손에 딱 맞는 마우스·키보드 세트','업무 장비','사무용 무선 마우스·키보드 세트. 9~10만원대 모델을 구매 후보로 검토해요. 모델·배열·연결 방식은 지급 전 확인해요.',50000,15,true,'keyboard') on conflict(id) do update set name=excluded.name,category=excluded.category,description=excluded.description,price=excluded.price,active=excluded.active,icon=excluded.icon;
