insert into thankyou.exchange_products(id,name,category,description,price,stock,active,icon) values('usb-hub','연결 걱정 없는 USB-C 허브','업무 장비','업무용 USB-C 멀티허브 제안. 업무 PC·모니터의 포트와 출력 호환을 먼저 확인해요.',20000,20,true,'hub') on conflict(id) do update set name=excluded.name,category=excluded.category,description=excluded.description,price=excluded.price,active=excluded.active,icon=excluded.icon;
