insert into thankyou.exchange_products(id,name,category,description,price,stock,active,icon) values('privacy-filter','내 화면을 지키는 보안필름','업무 장비','모니터용 시야 차단 보안필름. 24~27형 등 실제 화면 크기·화면비·부착 방식을 지급 전 확인해요. 브랜드·규격에 따라 시세 차이가 커요.',50000,15,true,'monitor') on conflict(id) do update set name=excluded.name,category=excluded.category,description=excluded.description,price=excluded.price,active=excluded.active,icon=excluded.icon;
